const body = $input.first().json.body ?? $input.first().json;

const secret = $env.WEBHOOK_SECRET;
if (!secret || body.webhook_secret !== secret) {
  throw new Error('UNAUTHORIZED');
}

const tenantId = (body.tenant_id ?? '').toString().trim();
const phone = (body.customer_phone ?? '').toString().trim();
const order = body.order ?? {};

if (!phone) {
  throw new Error('MISSING customer_phone');
}

let digits = phone.replace(/\D/g, '');
if (digits.startsWith('0')) digits = '964' + digits.slice(1);
else if (digits.length === 10 && digits.startsWith('7')) digits = '964' + digits;

const instanceFromBody = (body.instance_name ?? '').toString().trim();
const instanceName = instanceFromBody
  || (tenantId ? 'tenant_' + tenantId.replace(/-/g, '_') : '');

if (!instanceName) {
  throw new Error('MISSING instance_name');
}

return [{
  json: {
    instanceName,
    phone: digits,
    order,
    tenant_id: tenantId,
    order_id: body.order_id ?? null
  }
}];

