const prev = $('Validate Payload').first().json;
let text = '';

try {
  const ds = $input.first().json;
  text = ds.choices?.[0]?.message?.content?.trim() ?? '';
} catch (e) {
  text = '';
}

// Fallback إذا فشل DeepSeek
if (!text) {
  const o = prev.order;
  const name = o.customer_name ?? 'عميلنا الكريم';
  const store = o.store_name ?? 'المحل';
  text = `مرحباً ${name}، شكراً لزيارتكم ${store} لغيار الزيت.\n`;
  if (o.vehicle) text += `المركبة: ${o.vehicle}\n`;
  if (o.oil) text += `الزيت: ${o.oil}\n`;
  if (o.total_iqd) text += `الإجمالي: ${o.total_iqd} د.ع\n`;
  if (o.invoice_id) text += `رقم الفاتورة: ${o.invoice_id}\n`;
  text += 'نراكم عند موعد الصيانة القادمة.';
}

return [{ json: { ...prev, message_text: text, source: text ? 'deepseek' : 'fallback' } }];

/**
 * n8n Code node: soft reconnect ثم sendText عبر WAHA (GOWS).
 * عقدة «WAHA Send» في workflow إشعارات غيار الزيت.
 *
 * متغيرات البيئة في n8n:
 *   WAHA_API_KEY
 *   WAHA_BASE_URL (افتراضي داخلي: http://naboo-waha:3000)
 *
 * شكل الرد متوافق مع عقدة Evolution السابقة (ok/reason/mode/…).
 */
const prev = $input.first().json;
if (prev._abort) {
  return [{ json: prev }];
}

const WAHA_BASE = String(
  $env.WAHA_BASE_URL || 'http://naboo-waha:3000',
).replace(/\/$/, '');
const WAHA_KEY = String($env.WAHA_API_KEY || '').trim();
const SOFT_TIMEOUT_MS = 12000;
const POLL_MS = 1500;

const instance = (prev.instanceName || '').toString().trim();
const phoneRaw = (prev.phone || '').toString().trim();
const text = (prev.message_text || '').toString();

function fail(reason, detail, extra = {}) {
  return [{
    json: {
      ok: false,
      reason,
      detail: detail || '',
      mode: extra.mode || '',
      pdf_bytes_est: 0,
      tenant_id: prev.tenant_id || '',
      order_id: prev.order_id ?? null,
      source: prev.source || '',
      sent_to: extra.sent_to || phoneRaw || '',
      instanceName: instance,
      secret_used: prev.secret_used || '',
      provider: 'waha',
      ...extra,
    },
  }];
}

if (!WAHA_KEY) return fail('missing_field', 'WAHA_API_KEY_env');
if (!instance) return fail('missing_field', 'instance_name');
if (!phoneRaw) return fail('missing_field', 'phone');
if (!String(text).trim()) return fail('missing_field', 'message_text');

function normalizeIraqDigits(raw) {
  let d = String(raw).replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('964')) return d;
  if (d.startsWith('0')) return `964${d.slice(1)}`;
  if (d.length === 10 && d.startsWith('7')) return `964${d}`;
  return d;
}

const phone = normalizeIraqDigits(phoneRaw);
if (!phone) return fail('invalid_phone', 'normalize_failed');
const chatId = `${phone}@c.us`;

async function waha(path, opts = {}) {
  return this.helpers.httpRequest({
    method: opts.method || 'GET',
    url: `${WAHA_BASE}${path}`,
    headers: {
      'X-Api-Key': WAHA_KEY,
      'Content-Type': 'application/json',
      ...(opts.headers || {}),
    },
    body: opts.body,
    json: true,
    timeout: opts.timeout || 15000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
}

function mapState(payload) {
  const status = String(payload?.status || '').toUpperCase().trim();
  return {
    state: status || 'UNKNOWN',
    open: status === 'WORKING',
  };
}

function statusOf(res) {
  return res?.statusCode ?? res?.status ?? 0;
}

async function readState() {
  const res = await waha.call(
    this,
    `/api/sessions/${encodeURIComponent(instance)}`,
    { method: 'GET' },
  );
  const code = statusOf(res);
  if (code === 404) {
    return { open: false, state: 'removed', notFound: true };
  }
  return { ...mapState(res.body), notFound: false, http: code };
}

async function softReconnect() {
  const started = Date.now();
  const initial = await readState.call(this);
  if (initial.notFound) {
    return {
      ok: false,
      skipped: 'instance_removed',
      finalState: 'removed',
      elapsedMs: 0,
    };
  }
  if (initial.open) {
    return {
      ok: true,
      skipped: 'already_open',
      finalState: 'WORKING',
      elapsedMs: 0,
    };
  }

  let restartOk = false;
  try {
    const r = await waha.call(
      this,
      `/api/sessions/${encodeURIComponent(instance)}/restart`,
      { method: 'POST', body: {} },
    );
    const code = statusOf(r);
    restartOk = code >= 200 && code < 300;
  } catch (_) {
    restartOk = false;
  }

  await new Promise((r) => setTimeout(r, 800));

  let finalState = initial.state || 'unknown';
  while (Date.now() - started < SOFT_TIMEOUT_MS) {
    const live = await readState.call(this);
    if (live.notFound) {
      return {
        ok: false,
        skipped: 'instance_removed',
        finalState: 'removed',
        elapsedMs: Date.now() - started,
        restartOk,
      };
    }
    finalState = live.state || finalState;
    if (live.open) {
      return {
        ok: true,
        finalState,
        elapsedMs: Date.now() - started,
        restartOk,
      };
    }
    await new Promise((r) => setTimeout(r, POLL_MS));
  }

  return {
    ok: false,
    finalState,
    elapsedMs: Date.now() - started,
    restartOk,
  };
}

async function sendTextOnce() {
  return waha.call(this, '/api/sendText', {
    method: 'POST',
    body: { session: instance, chatId, text },
    timeout: 30000,
  });
}

function looksDisconnected(detail, statusCode) {
  const lower = String(detail || '').toLowerCase();
  return (
    statusCode === 500 ||
    lower.includes('disconnect') ||
    lower.includes('not connected') ||
    lower.includes('failed') ||
    lower.includes('stopped') ||
    lower.includes('closed')
  );
}

let soft = null;
const before = await readState.call(this);
if (before.notFound) {
  return fail('instance_not_found', 'session_404', { sent_to: phone, mode: 'text' });
}
if (!before.open) {
  soft = await softReconnect.call(this);
  if (!soft.ok) {
    return fail(
      soft.skipped === 'instance_removed'
        ? 'instance_not_found'
        : 'whatsapp_disconnected',
      soft.finalState || 'not_open',
      {
        sent_to: phone,
        mode: 'text',
        soft_reconnect: false,
        soft_reconnect_elapsed_ms: soft.elapsedMs,
        soft_reconnect_meta: soft,
      },
    );
  }
}

let ok = false;
let reason = '';
let detail = '';
try {
  const sendRes = await sendTextOnce.call(this);
  const code = statusOf(sendRes);
  if (code >= 200 && code < 300) {
    ok = true;
    detail = String(sendRes.body?.id || '');
  } else {
    detail = String(
      sendRes.body?.message || sendRes.body?.error || code,
    ).slice(0, 400);
    if (looksDisconnected(detail, code)) {
      reason = 'whatsapp_disconnected';
      soft = await softReconnect.call(this);
      if (soft.ok) {
        const retry = await sendTextOnce.call(this);
        const rCode = statusOf(retry);
        if (rCode >= 200 && rCode < 300) {
          ok = true;
          reason = '';
          detail = String(retry.body?.id || '');
        } else {
          detail = String(
            retry.body?.message || retry.body?.error || rCode,
          ).slice(0, 400);
          reason = 'whatsapp_disconnected';
        }
      }
    } else if (code === 401 || code === 403) {
      reason = 'unauthorized';
    } else if (code === 404) {
      reason = 'instance_not_found';
    } else {
      reason = 'waha_error';
    }
  }
} catch (e) {
  const msg = (e.message || String(e)).toLowerCase();
  detail = String(e.message || e).slice(0, 400);
  if (looksDisconnected(msg, 0)) {
    reason = 'whatsapp_disconnected';
    soft = await softReconnect.call(this);
    if (soft.ok) {
      try {
        const retry = await sendTextOnce.call(this);
        const rCode = statusOf(retry);
        if (rCode >= 200 && rCode < 300) {
          ok = true;
          reason = '';
          detail = String(retry.body?.id || '');
        } else {
          detail = String(
            retry.body?.message || retry.body?.error || rCode,
          ).slice(0, 400);
          reason = 'whatsapp_disconnected';
        }
      } catch (e2) {
        detail = String(e2.message || e2).slice(0, 400);
        reason = 'whatsapp_disconnected';
      }
    }
  } else if (msg.includes('timeout') || msg.includes('timed out')) {
    reason = 'timeout';
  } else if (msg.includes('401') || msg.includes('403')) {
    reason = 'unauthorized';
  } else if (msg.includes('404')) {
    reason = 'instance_not_found';
  } else {
    reason = 'waha_error';
  }
}

return [{
  json: {
    ok,
    reason,
    mode: 'text',
    detail,
    pdf_bytes_est: 0,
    tenant_id: prev.tenant_id,
    order_id: prev.order_id,
    source: prev.source,
    sent_to: phone,
    chat_id: chatId,
    instanceName: instance,
    secret_used: prev.secret_used || '',
    soft_reconnect: soft?.ok === true,
    soft_reconnect_elapsed_ms: soft?.elapsedMs ?? null,
    soft_reconnect_meta: soft,
    provider: 'waha',
  },
}];
